ee:message.ee:set-payload:
%dw 2.0
output application/json

var isStringResult = vars.postLisimOtpResponse.result is String
var isObjectResult = vars.postLisimOtpResponse.result is Object
var hasMessageServer =
  isObjectResult and vars.postLisimOtpResponse.result.messageServer != null

---
{
  code: "200",
  message:
    if (isStringResult)
      vars.postLisimOtpResponse.result
    else if (hasMessageServer)
      vars.postLisimOtpResponse.result.messageServer
    else
      "envio exitoso"
}
++
(
  if (isStringResult)
    { result: vars.postLisimOtpResponse.result }
  else if (isObjectResult and not hasMessageServer)
    { result: vars.postLisimOtpResponse.result }
  else
    {}
)
